    "title": "Mapping Rocks From Space",
    "teaser": "The Himalayan mountain range is known for its majestic beauty and towering heights, but the very features that make it famous can keep scientists from understanding its details. To make sense of the history of this mountain range, geologists need to see the rocks that they are made of.",
